import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.mockito.Mockito.*;

public class Element_nextElementSibling_TriageGen0Test {

    private Element parentElement;
    private Element firstChild;
    private Element secondChild;
    private Element thirdChild;

    @Before
    public void setUp() {
        parentElement = mock(Element.class);
        firstChild = mock(Element.class);
        secondChild = mock(Element.class);
        thirdChild = mock(Element.class);

        when(parentElement.children()).thenReturn(Arrays.asList(firstChild, secondChild, thirdChild));

        when(firstChild.indexInList(firstChild, parentElement.children())).thenReturn(0);
        when(secondChild.indexInList(secondChild, parentElement.children())).thenReturn(1);
        when(thirdChild.indexInList(thirdChild, parentElement.children())).thenReturn(2);
    }

    @Test
    public void testNextElementSibling_withNextSibling() {
        when(firstChild.parent()).thenReturn(parentElement);
        when(secondChild.parent()).thenReturn(parentElement);

        Element result = firstChild.nextElementSibling();
        assertEquals(secondChild, result);
    }

    @Test
    public void testNextElementSibling_withoutNextSibling() {
        when(thirdChild.parent()).thenReturn(parentElement);

        Element result = thirdChild.nextElementSibling();
        assertNull(result);
    }

    @Test(expected = NullPointerException.class)
    public void testNextElementSibling_withNullParent() {
        Element element = mock(Element.class);
        when(element.parent()).thenReturn(null);
        when(element.indexInList(element, parentElement.children())).thenReturn(1);

        element.nextElementSibling();
    }

    @Test
    public void testNextElementSibling_withSingleChild() {
        when(firstChild.parent()).thenReturn(parentElement);

        Element result = firstChild.nextElementSibling();
        assertNull(result);
    }

    @Test
    public void testNextElementSibling_withEmptyChildren() {
        Element parentWithNoChildren = mock(Element.class);
        when(parentWithNoChildren.children()).thenReturn(List.of());

        Element childWithNoSiblings = mock(Element.class);
        when(childWithNoSiblings.parent()).thenReturn(parentWithNoChildren);
        when(childWithNoSiblings.indexInList(childWithNoSiblings, parentWithNoChildren.children())).thenReturn(0);

        Element result = childWithNoSiblings.nextElementSibling();
        assertNull(result);
    }
}
